/// <summary>
/// This extension handles the Rebate Group Table Events customizations
/// </summary>
internal final class METTAMRebateGroupTableEventHandler
{
}

Method.Source:
    /// <summary>
    /// Dont allow Rebate group deletion if it is being used by any rebate deal.
    /// </summary>
    /// <param name="sender">TAMRebateGroup table</param>
    /// <param name="e">ValidatingDelete event</param>
    [
        DataEventHandler(tableStr(TAMRebateGroup), DataEventType::ValidatingDelete),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
    ]
    public static void TAMRebateGroup_onValidatingDelete(Common sender, DataEventArgs e)
    {
        TAMRebateGroup rebateGroup =  sender as TAMRebateGroup;

        TAMRebateGroupLink rebateGroupLink;

        select firstonly1 RecId from rebateGroupLink
            where rebateGroupLink.RebateGroupId == rebateGroup.RebateGroupId;
        if(rebateGroupLink)
        {
            Error("@MET:RebateItemGroupDeleteErrorMessage");
        }
    }
